{
  "hypotheses": [
    {
      "table": "fda_snapshot.recalls",
      "column": "openfda_product_ndc",
      "transform": "segments_to_11",
      "rationale": "The column openfda_product_ndc is designed to hold NDC identifiers in the FDA format. Although the provided samples are null, the column name and FDA context strongly suggest it contains 11-digit NDCs potentially with hyphens (segments 5-4-2). The segments_to_11 transform normalizes such values by ensuring proper segment padding to exactly 11 digits, matching the hospital's hospital.item_master.ndc11 format."
    },
    {
      "table": "fda_snapshot.shortages",
      "column": "package_ndc",
      "transform": "strip_hyphens_lpad_11",
      "rationale": "The package_ndc column contains NDC-like codes with hyphens (e.g., '0009-0225-02'). These are 11-digit NDCs in 5-4-2 segment format with hyphens. The strip_hyphens_lpad_11 transform first removes the hyphens and then left-pads the resulting digit string to 11 characters, directly producing the hospital's ndc11 format."
    },
    {
      "table": "fda_snapshot.ndc_packages",
      "column": "product_ndc",
      "transform": "lpad_11",
      "rationale": "The product_ndc column contains NDC codes without the final package segment (e.g., '82953-020'). These are 10-digit or fewer codes missing a check digit or trailing segment. The lpad_11 transform left-pads the digit string to 11 characters, which aligns with the hospital's 11-digit NDC11 requirement, likely adding a missing check digit or segment."
    },
    {
      "table": "wholesaler.catalog",
      "column": "ndc",
      "transform": "lpad_11",
      "rationale": "The wholesaler.catalog ndc column contains 9 or 10 digit NDC codes (e.g., '143926901', '25021070102'). These are shorter than the hospital's 11-digit format. The lpad_11 transform left-pads the values with leading zeros to reach 11 digits, standardizing them to the hospital's ndc11 format."
    }
  ]
}

